    {btn_key = "tog_1", configName = "flower_rank_reward", text_key = "tog_1_text", tabIndex = 1, tab_name = "flower_text_0054"}, 
    {btn_key = "tog_2", configName = "flower_guild_reward", text_key = "tog_2_text", tabIndex = 2, tab_name = "flower_text_0055"}, 
}

function M:onCreate()
    M.super.onCreate(self)
    self.tab=true
    if self.m_params.is_rta_rank_rewards then
