function M:setRankData()
    if not self.m_rankAwards_data then
        self.m_rankAwards_data = {}
        for index = 1, table.nums(__TAB_BTN_NODE) do
            local itemData =  __TAB_BTN_NODE[index]
            local configXlsxData = ConfigManager:getCfgByName(itemData.configName)
            local cfgData = configXlsxData[self.m_versionId]
            if not self.m_rankAwards_data[index] then
                self.m_rankAwards_data[index] = {}
            end
            if self.m_params.is_rta_rank_rewards then
                cfgData=cfgData[self.m_params.tier]

                local pairsByKeys=function(t)
                    local a={}
                    for i in pairs(t) do
                        a[#a+1]=i
                    end
                    table.sort(a)
                    local j=0
                    return function()
                        j=j+1
                        return a[j],t[a[j]]
                    end
                end

                for rank, itemData in pairsByKeys(cfgData) do
                    local _rank=rank
                    if itemData.rank_dis[2]==3 then
                        table.insert(self.m_rankAwards_data[index], {
                            rank = {[1]=2},
                            award = itemData.awards,
                        })
                        table.insert(self.m_rankAwards_data[index], {
                            rank = {[1]=3},
                            award = itemData.awards,
                        })
                    else
                        table.insert(self.m_rankAwards_data[index], {
                            rank = itemData.rank_dis,
                            award = itemData.awards,
                        })
                    end

                end
            else
                for _, itemData in pairs(cfgData) do
                    table.insert(self.m_rankAwards_data[index], {
                        rank = itemData.rank,
                        award = itemData.rank_rewards,
                    })
                end
            end

            Logger.logWarning(self.m_rankAwards_data)
        end
    end
end

return M
